function equivalenceVol(Ca, Va, Cb){ if(!Cb) return NaN; return Ca*Va/Cb; }
function phAt(Ca, Va, Cb, Vb){
  var nA = Ca*Va, nB = Cb*Vb, tot = Va+Vb;
  if(nB < nA){ var h=(nA-nB)/tot; return -Math.log10(h); }
  if(Math.abs(nB-nA) < 1e-12) return 7;
  var oh=(nB-nA)/tot; return 14 + Math.log10(oh);
}
function curve(Ca, Va, Cb, steps){
  steps=(steps==null)?50:steps; var Ve=equivalenceVol(Ca,Va,Cb); var out=[];
  for(var i=0;i<=steps;i++){ var Vb=Ve*i/steps*1.2; out.push({Vb:Vb, pH:phAt(Ca,Va,Cb,Vb)}); }
  return out;
}
var EXPORTS={ equivalenceVol:equivalenceVol, phAt:phAt, curve:curve };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TitrationForgePure = EXPORTS; }
